// Original teaching examples and questions, organized around requested study topics.
export const TCS_REVISION='2026-10-29.tcs1';
export const TCS_UNITS=['Python building blocks','Data contracts and SQL','Git snapshots','HTTP and browser requests','Security boundaries','AI and evaluation','Trace and review'];
export const TCS_SOURCES={
 python:'https://docs.python.org/3.14/tutorial/controlflow.html',objects:'https://docs.python.org/3.14/reference/datamodel.html',deque:'https://docs.python.org/3.14/library/collections.html#collections.deque',sql:'https://sqlite.org/lang_select.html',git:'https://git-scm.com/docs/git-add',reset:'https://git-scm.com/docs/git-reset',uri:'https://www.rfc-editor.org/rfc/rfc3986.html',http:'https://www.rfc-editor.org/rfc/rfc9110.html',cache:'https://www.rfc-editor.org/rfc/rfc9111.html',offline:'https://developer.mozilla.org/en-US/docs/Web/API/Cache',fetch:'https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch',xss:'https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html',injection:'https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html',oauth:'https://www.rfc-editor.org/rfc/rfc9700.html',firebase:'https://firebase.google.com/docs/rules/basics',firebaseKeys:'https://firebase.google.com/docs/projects/api-keys',firebaseAuth:'https://firebase.google.com/docs/auth/web/password-auth',split:'https://scikit-learn.org/stable/modules/cross_validation.html',regularization:'https://scikit-learn.org/stable/modules/learning_curve.html',fewshot:'https://arxiv.org/abs/2005.14165',rag:'https://arxiv.org/abs/2309.15217',consistency:'https://arxiv.org/abs/2203.11171'
};
function lesson(v){
 const options=v.choices.map((label,i)=>({id:'choice-'+i,label}));
 // Vary answer positions while preserving stable option IDs across renders.
 const rotation=v.id.length%options.length;
 return {version:TCS_REVISION,minutes:15,prerequisites:[],terms:[],tasks:[],sources:[],...v,options:[...options.slice(rotation),...options.slice(0,rotation)],answer:'choice-'+v.correct,
 contract:'Choose the one claim that follows from this lesson and the stated example. This checks recognition only. Explain your reasoning separately; written notes are self-assessment.',
 solution:v.choices[v.correct],bug:v.choices[(v.correct+1)%v.choices.length],complexity:v.cost||'One bounded authored-choice comparison takes O(1) time and space; this is not an executed system or model benchmark.',fixtures:v.choices.map((_,i)=>({choice:'choice-'+i,correct:i===v.correct}))};
}
export const TCS_LESSONS=[
lesson({id:'guards-and-return',unit:0,title:'Read a program one decision at a time',goal:'Distinguish missing input, empty input, branch selection and the end of a function.',
 basics:'A variable names a value. A list stores values in order. A function accepts inputs and returns one result. Indentation groups the instructions under a condition or loop. None represents a missing value, while [] is a real list containing no items. Both are falsy, so test the more specific missing case first when the contract treats them differently. Read the guard clauses before tracing the main calculation.',
 worked:'A return immediately leaves the function, even if it appears inside a loop. In this example max reads the whole supplied list, rather than just the current item. The loop is unnecessary because its body returns on the first iteration. Calling min or max on an empty list raises an error; the guards prevent that.',
 code:'def summary(values):\n    if values is None:\n        return "missing"\n    if not values:\n        return "empty"\n    for item in values:\n        return max(values)\n\nprint(summary([6, 2, 11]))',result:'11',pitfall:'Treating None and [] as identical loses information when the input contract distinguishes them.',question:'Why does the example return 11 during its first loop iteration?',choices:['max(values) examines the whole list and return exits the function.','A loop always finishes all iterations before returning.','The first item is automatically replaced by the largest.'],correct:0,feedback:'The call max(values) explicitly receives the whole list. The current item is never used.',tasks:[['python','tcs-guard-return']],terms:[['Guard clause','An early test that handles a special case.'],['Return','End this call and give a result to its caller.']],sources:['python'],followUp:'Rewrite the example without its redundant loop. Predict None, [], [0] and a list of negative values.'}),
lesson({id:'functions-as-values',unit:0,title:'Pass a function and return a function',goal:'Understand higher-order functions without assuming a library is required.',basics:'A function is an object that can be assigned to a variable, passed as an argument or returned by another function. A higher-order function does at least one of the last two things. Writing scale passes a callable; writing scale(4) calls it now and passes its result. This distinction lets one loop reuse different behavior without duplicating its traversal.',worked:'make_multiplier returns the inner function, rather than calling it. That returned function remembers factor from the enclosing call. The name times_three then refers to a callable. functools provides useful helpers such as partial and reduce, but ordinary def and return are enough for this pattern. Account for callback cost rather than assuming every callback is constant time.',code:'def make_multiplier(factor):\n    def multiply(value):\n        return value * factor\n    return multiply\n\ntimes_three = make_multiplier(3)\nprint(times_three(5))',result:'15',pitfall:'Calling a function when you intended to pass it can run work too early and pass the wrong type.',question:'What does make_multiplier(3) return?',choices:['The integer 3.','A callable that can later multiply an input by 3.','A special functools object that needs importing.'],correct:1,feedback:'The return expression is multiply, a function object. Parentheses are used later to call it.',tasks:[['python','tcs-higher-order']],terms:[['Callable','A value you can invoke with parentheses.'],['Closure','A function that retains access to an enclosing binding.']],sources:['python'],followUp:'Pass a named function, then a lambda, into apply_each. Explain why zero must not be skipped.'}),
lesson({id:'choose-a-deque',unit:0,title:'Choose a collection from the operations you need',goal:'Compare deques, lists, stacks and indexed trees using concrete costs.',basics:'A queue normally removes the oldest item first. A stack removes the most recently added item first. A double-ended queue, called a deque, supports adding and removing at both ends. Choose the structure from the operations the task needs, rather than a familiar name. Python collections.deque has approximately constant-time append and pop operations at either end.',worked:'A Python list has fast indexed access and amortized constant-time append at the right. Removing its first item shifts the later references, which takes linear time. A C++ vector has a similar front-erasure cost; language-specific details still matter. A segment tree solves range query/update problems in logarithmic time, rather than constant-time removal from either end. Middle access on a deque is not its strength.',code:'from collections import deque\nqueue = deque([4, 9])\nqueue.appendleft(2)\nprint(queue.popleft())\nprint(queue.pop())\nprint(list(queue))',result:'2\n9\n[4]',pitfall:'A structure that is good at one operation is not automatically good at every operation.',question:'A workload repeatedly removes from both ends. Which Python structure directly supports that?',choices:['A list because pop(0) never moves anything.','A segment tree because every operation is O(1).','collections.deque.'],correct:2,feedback:'Deque end operations fit this workload. State which operation your complexity claim describes.',tasks:[['python','tcs-deque']],terms:[['Amortized','An average cost over a sequence of operations, allowing occasional expensive ones.'],['LIFO','Last in, first out, the stack order.']],sources:['deque'],followUp:'Explain why a deque may be a poor choice for repeated indexing into its middle.'}),
lesson({id:'byte-formatting',unit:0,title:'Turn a formatting rule into exact arithmetic',goal:'Handle unit thresholds, decimal places, rounding and bounds deliberately.',basics:'A byte count is an integer. Binary units increase by 1024, so KiB means 1024 bytes and MiB means 1024 KiB. Decimal KB conventionally means 1000 bytes; name the convention explicitly. Keep a unit index and a scale, then move up while the next threshold is reached. The comparison must include equality so exactly 1024 bytes becomes one KiB.',worked:'1536 divided by 1024 is 1.5. A display contract might require 1.50KiB while exactly 2048 becomes 2KiB. These are formatting choices, not changes to the underlying count. Choose a rounding rule and a maximum unit. Integer arithmetic can preserve exact large counts; blindly converting unrestricted integers to float can lose precision. Our task fixes the domain and rounds half up without changing the selected unit after rounding.',code:'size = 1536\nwhole, remainder = divmod(size, 1024)\nprint(whole, remainder)\nprint(f"{size / 1024:.2f}KiB")',result:'1 512\n1.50KiB',pitfall:'Using > rather than >= misses an exact unit boundary. General numeric formatting may omit required trailing zeros.',question:'Under the linked contract, how should exactly 1024 bytes be displayed?',choices:['1024B because the loop uses strict greater-than.','1KiB.','1.00KB, regardless of the named unit convention.'],correct:1,feedback:'The boundary is inclusive, and a whole coefficient omits decimal places. KiB names the binary unit.',tasks:[['python','tcs-size-format']],terms:[['Coefficient','The number shown before a unit.'],['Boundary fixture','A test exactly at or beside a rule threshold.']],sources:['python'],followUp:'Predict 0, 1023, 1024 and 1536 before checking. Explain the specified maximum-unit rounding behavior.'}),
lesson({id:'objects-and-composition',unit:0,title:'Make objects keep their own state',goal:'Build classes with constructors, special methods and direct children.',basics:'A class describes behavior; an instance is one object created from that class. __init__ initializes its fields. self identifies the instance receiving a method call. self.children = [] makes a fresh list for each new object. A mutable list on the class itself is shared across instances, which usually breaks independent container behavior.',worked:'Python calls __len__ for len(obj) and __str__ for str(obj). Their meanings come from your contract: a packet length might mean bytes while a bundle length means direct child count. Composition means a container holds references to child objects. Counting direct children does not recurse into grandchildren. Sort rendered strings when that is the required order; sorting by size or raw object identity answers a different question.',code:'class Label:\n    def __init__(self, text):\n        self.text = text\n    def __str__(self):\n        return self.text.upper()\n\nprint(str(Label("map")))',result:'MAP',pitfall:'Do not confuse a class-level shared list with an instance-owned list, or direct count with recursive count.',question:'Where should each new Bundle create its own children list?',choices:['Once on the class, so every bundle shares it.','Inside listing, erasing it each time.','Inside __init__ as self.children = [].'],correct:2,feedback:'__init__ runs for each new instance. Its list assignment prevents one container from acquiring another container\'s children.',tasks:[['python','tcs-object-model']],terms:[['Instance attribute','State attached to one object.'],['Composition','One object contains or refers to other objects.']],sources:['objects'],followUp:'Create two empty bundles, add to only one, and explain why the other must remain empty.'}),
lesson({id:'mutual-recursion',unit:0,title:'Follow calls down and results back up',goal:'Trace mutually recursive functions and justify termination.',basics:'Recursion is a function call that eventually leads back to the same function. Mutual recursion alternates between functions. Both still need base cases and a measure that moves toward them. A factorial-like product uses 1 at zero, because multiplying by 1 preserves the accumulated product. Returning zero at the base would make every result zero.',worked:'Expand one call at a time before evaluating the pending multiplications. In the example, a(3) waits for b(2), which waits for a(1), which waits for b(0). Only then do results unwind. Alternating names does not save stack space. These small bounded tasks are suitable for tracing; deep recursion can hit Python\'s recursion limit, and large integers increase arithmetic cost.',code:'def a(n):\n    return 1 if n == 0 else n * b(n - 1)\ndef b(n):\n    return 1 if n == 0 else n * a(n - 1)\nprint(a(3))',result:'6',pitfall:'A back-and-forth call is not proof of termination. Identify the value that decreases and its lower bound.',question:'Which fact establishes that these calls reach the base case for nonnegative n?',choices:['Each call reduces n by one until zero.','There are two function names.','Multiplication always stops recursion automatically.'],correct:0,feedback:'The decreasing nonnegative argument supplies the progress measure. Both functions preserve it.',tasks:[['python','tcs-mutual-recursion']],terms:[['Base case','A case that returns without another recursive call.'],['Call stack','The pending function calls waiting for results.']],sources:['python'],followUp:'Draw the pending calls for n=4, then compare stack use with an iterative product.'}),
lesson({id:'extract-the-contract',unit:1,title:'Read the full question before writing the answer',goal:'Identify missing facts rather than inventing a problem from a partial screenshot.',basics:'A solution begins with a contract: valid inputs, required output, boundaries, ordering and failure behavior. A partial prompt or visible column list is not enough to determine the intended query. Ask for the missing condition, complete schema, dialect and sample-output meaning. State uncertainty precisely instead of filling gaps with plausible guesses.',worked:'A request to find large rooms is ambiguous. Does large mean capacity > 48 or >= 48? Should inactive rooms remain? Which output columns and order are required? The completed example below answers each point and makes an equality fixture possible. Samples illustrate a rule; they do not replace it. Build changed inputs that distinguish competing interpretations.',code:'Input: rooms(id, label, capacity, active)\nOutput: room_id only\nRule: capacity > 48, regardless of active\nOrder: room_id ascending\nEmpty result: no rows\nDialect in this browser: SQLite',result:'A capacity of 48 is excluded. An inactive room with capacity 60 is included.',pitfall:'Do not guess an extra filter from the business story or infer an output contract from a cut-off prompt.',question:'A prompt omits the filter condition and required output. What is the useful next step?',choices:['Write a familiar join and hope it matches.','Ask for the missing condition, schema and output contract.','Treat the sample rows as the entire hidden dataset.'],correct:1,feedback:'An explicit missing-facts request is more reliable than inventing a query specification.',tasks:[['sql','tcs-sql-threshold']],terms:[['Contract','The precise behavior a solution must satisfy.'],['Fixture','A concrete input and required result used for checking.']],sources:['sql'],followUp:'Write a five-line contract for a new table query before touching the editor.'}),
lesson({id:'sql-filter-order',unit:1,title:'Choose columns, filter rows, then order results',goal:'Write SELECT, WHERE and ORDER BY from a plain-language requirement.',basics:'A table stores rows with named columns. SQL asks for a result without manually looping over records. SELECT chooses output values, FROM names the input and WHERE keeps rows whose condition is true. AS names an output column. ORDER BY gives a required result order; do not assume stored row order will satisfy the contract.',worked:'The comparison > excludes equality while >= includes it. Test one row below, one exactly at and one above the threshold. An empty match set is a valid result, not a reason to invent a zero row. The linked task executes real SQLite. Its simple syntax is also supported by MySQL, but differences in other SQL features mean one engine\'s pass does not verify every dialect.',code:'SELECT id AS room_id\nFROM rooms\nWHERE capacity > 48\nORDER BY id ASC;',result:'One room_id per qualifying row, in ascending numeric order. A room with capacity 48 is absent.',pitfall:'SQL output is not guaranteed to follow insertion order. A boundary change can silently change the answer.',question:'Which condition expresses strictly more than 48?',choices:['capacity >= 48','capacity = 48','capacity > 48'],correct:2,feedback:'Strictly more excludes 48. Use changed fixtures to expose >= mistakes.',tasks:[['sql','tcs-sql-threshold']],terms:[['Row','One stored record.'],['Alias','A chosen output name introduced with AS.']],sources:['sql'],followUp:'Change the threshold and predict which exact-boundary row changes membership.'}),
lesson({id:'sql-left-join-count',unit:1,title:'Keep parents that have no matching children',goal:'Use LEFT JOIN, NULL-aware counting and deterministic grouping.',basics:'A join connects related rows through keys. LEFT JOIN preserves every left input row, even when no right row matches. For an unmatched parent, the joined child columns are NULL. COUNT(child.id) ignores NULL and returns zero; COUNT(*) counts the preserved row and returns one. Group by the parent identity, because distinct parents can share a name.',worked:'Filter which parents are eligible in WHERE or before the join. A parent condition placed only in ON changes matching, but preserves the ineligible parent as an unmatched row. Conditions on children belong in ON when parents without qualifying children must survive. Give every required tie-breaker explicitly. Our task sorts counts descending, then names and IDs ascending.',code:'SELECT r.id, COUNT(b.id) AS total\nFROM rooms r\nLEFT JOIN bookings b ON b.room_id = r.id\nWHERE r.active = 1\nGROUP BY r.id\nORDER BY total DESC, r.id ASC;',result:'An active room with no bookings has total 0. An inactive room is absent.',pitfall:'Moving r.active=1 only into ON does not remove inactive rooms from a LEFT JOIN.',question:'Which count gives zero for a preserved room with no booking?',choices:['COUNT(b.id), where b.id is a non-NULL child primary key.','COUNT(*).','COUNT(r.id), the preserved parent key.'],correct:0,feedback:'Only the child key becomes NULL on the unmatched row. Parent keys and the row itself still exist.',tasks:[['sql','tcs-sql-zero-count']],terms:[['NULL','A marker for an absent or unknown SQL value.'],['Cardinality','How many rows a relation or join produces.']],sources:['sql'],followUp:'Predict a zero-child parent, an inactive parent with bookings, and two parents sharing a label.'}),
lesson({id:'git-three-snapshots',unit:2,title:'Understand HEAD, the index and your working files',goal:'Read staged and unstaged differences without guessing a unique command history.',basics:'Git compares three important states. HEAD identifies the current commit snapshot. The index is the snapshot prepared for the next commit. The working tree contains your current files. git add copies a file\'s current contents into the index; later edits do not automatically update that staged copy. The same filename can therefore have staged and unstaged changes at once.',worked:'In this example, HEAD holds version A, the index holds B and the working file holds C. git diff shows B to C, while git diff --cached shows A to B. Staging then editing is one way to reach this state, but status alone cannot prove the exact history. reset --soft moves HEAD while preserving index and files, including pre-existing edits. Mixed resets replace the index; hard resets also replace tracked working files and can discard work. This lesson executes no destructive Git commands.',code:'HEAD:         memo.txt = "A"\nIndex:        memo.txt = "B"\nWorking file: memo.txt = "C"\n\ngit diff          # B -> C\ngit diff --cached # A -> B',result:'One file has both staged and unstaged differences.',pitfall:'A reset mode describes which states change, not a universal promise that all other differences are absent.',question:'After git add memo.txt, you edit the file again. What can status show?',choices:['Two different files with the same name.','Only unstaged changes; the staged version disappears.','Both staged and unstaged changes for the same file.'],correct:2,feedback:'The index keeps the staged snapshot while the working tree holds the later edit.',terms:[['Index','The snapshot currently prepared for a commit.'],['HEAD','The reference to the current checked-out commit.']],sources:['git','reset'],followUp:'Explain the two diffs using A, B and C. State the recovery risk before describing any reset.'}),
lesson({id:'resource-urls',unit:3,title:'Design resource URLs and choose HTTP methods',goal:'Separate URL conventions from protocol rules.',basics:'A URL has a scheme, host, optional port, path and possibly query and fragment components. Scheme and host are case-insensitive; paths and queries are generally case-sensitive. Lowercase, readable resource paths are useful API conventions, not a rule that all URLs ignore case. Clients should follow the API\'s documented links and construction rules.',worked:'GET reads a representation. POST submits work or creates under a collection. PUT replaces the target representation; PATCH applies a partial update; DELETE requests removal. Resource nouns such as /notes/7 keep operations in the method rather than inventing /deleteNote. When a resource moves, a redirect can preserve compatibility. A 308 preserves the method; a 301 can allow POST to become GET. Choose based on the actual migration and client behavior.',code:'GET    /notes/7\nPATCH  /notes/7\nDELETE /notes/7\n\nhttps://api.study.example/Notes/7\nhttps://api.study.example/notes/7',result:'The final two paths can identify different resources. The host name\'s letter case does not create a different host.',pitfall:'Short paths and lowercase style are design guidance, not universal validity or case-insensitivity rules.',question:'Which URL component is generally case-sensitive?',choices:['The host name only.','The path.','Neither host nor path can ever be case-sensitive.'],correct:1,feedback:'RFC 3986 treats scheme and host differently from the generally case-sensitive remaining components.',tasks:[['python','tcs-origin-check']],terms:[['Resource','The thing identified by a URI.'],['Idempotent','Repeating a request has the same intended effect as sending it once.']],sources:['uri','http'],followUp:'Design a note deletion endpoint and explain why a POST migration may need 308 rather than 301.'}),
lesson({id:'http-error-contracts',unit:3,title:'Return status codes that clients can act on',goal:'Combine meaningful HTTP status with a safe structured error body.',basics:'A status code communicates the broad result independently of prose. 400 describes a bad request, 401 missing or invalid authentication, 403 refused authorization, 404 an unavailable resource, 409 a state conflict, and 500 an unexpected server failure. Exact application contracts and deliberate information hiding can affect which response is appropriate. A 401 response includes the applicable authentication challenge.',worked:'Use a stable application error code and a useful message. Optional field details help a form identify invalid inputs. Keep stack traces, database internals and secrets in protected server logs. A success status with an error-only body misleads clients and monitoring. A redirect to a human website is generally unsuitable for a machine API error. Clients should branch on status and stable codes, rather than scraping English messages.',code:'HTTP/1.1 409 Conflict\nContent-Type: application/json\n\n{"code":"NOTE_VERSION_CONFLICT",\n "message":"Reload the note before saving again."}',result:'The client can recognize a conflict and offer a recovery action without parsing the message wording.',pitfall:'A generic 500 hides expected client or state errors. A detailed body does not justify leaking internal exception text.',question:'A stale version tries to overwrite a newer note. Under this example contract, which response fits?',choices:['200 with an error message only.','302 to an unrelated website.','409 with a stable conflict code and recovery message.'],correct:2,feedback:'The failure concerns the resource\'s current state. A structured conflict response lets the client recover.',terms:[['Status code','The protocol-level response category.'],['Error contract','Stable fields and behavior a client can rely on after failure.']],sources:['http'],followUp:'Describe separate responses for malformed input, missing authentication, cross-owner access and a database outage.'}),
lesson({id:'http-cache-directives',unit:3,title:'Separate cache permission, freshness and revalidation',goal:'Understand public, private, no-store, no-cache and age directives.',basics:'A private cache serves one user agent; a shared cache can serve multiple users. public explicitly permits shared caching subject to other rules. private excludes shared storage. no-store tells HTTP caches not to store the response. no-cache permits storage but requires validation before reuse. max-age sets a freshness lifetime; s-maxage sets a shared-cache lifetime. must-revalidate restricts stale reuse.',worked:'A cacheable unauthenticated response can be shared without the public keyword. Authorization requests have additional rules; public, s-maxage or must-revalidate can permit reuse under RFC 9111 conditions. This does not make personalized content safe to share across users. First decide who is allowed to reuse a response, then its freshness and validation policy. These headers govern HTTP caching, not every application-managed storage system.',code:'Public illustration:\nCache-Control: public, max-age=120\n\nSensitive personal response policy:\nCache-Control: no-store',result:'The first can allow shared reuse while fresh. The second asks HTTP caches not to store it.',pitfall:'A shorter lifetime reduces staleness; it does not establish who is allowed to read a cached representation.',question:'Which directive permits storage but requires validation before reuse?',choices:['no-cache','no-store','private always means validate every time'],correct:0,feedback:'no-cache and no-store express different rules. private determines cache scope, not a universal validation interval.',terms:[['Freshness','Whether a stored response can be reused without validation.'],['Revalidation','Checking with the origin whether a stored representation is still usable.']],sources:['cache'],followUp:'Explain a public catalogue policy and a personal-profile policy, including which cache system obeys them.'}),
lesson({id:'fetch-response-stages',unit:3,title:'Handle network, HTTP and body parsing separately',goal:'Read fetch code without assuming every failure rejects its promise.',basics:'fetch returns a promise for a Response. An ordinary HTTP 404 or 500 usually resolves that promise; response.ok is true only for status 200 through 299. Network failures, aborts and some request failures can reject. A successfully received response can still have an invalid JSON body. Handle these as separate stages with useful recovery messages.',worked:'response.json() is an asynchronous method that reads and parses the body. It is not a property containing already parsed data. Reading consumes the body stream. Clone an unused response first if two independent consumers truly need it, rather than calling json twice on the same response. An HTTP error body can itself be useful JSON, so production error handling can parse a structured error safely while preserving status.',code:'const response = await fetch("/api/notes");\nif (!response.ok) {\n  throw new Error(`HTTP ${response.status}`);\n}\nconst notes = await response.json();',result:'HTTP failure is detected explicitly. Invalid JSON can still reject after an OK status.',pitfall:'A fulfilled fetch promise does not prove an application request succeeded or that JSON parsing will succeed.',question:'The server returns HTTP 404 with a valid JSON body. What normally happens to fetch?',choices:['It always rejects before a Response exists.','It resolves a Response whose ok value is false.','It automatically redirects to a generic error page.'],correct:1,feedback:'Check status explicitly. Network/request failure and body parsing are separate promise outcomes.',terms:[['Promise','A value representing an asynchronous result.'],['Consumed body','A response stream that has already been read.']],sources:['fetch'],followUp:'Explain how you would distinguish offline, HTTP 403 and an HTML response that fails JSON parsing.'}),
lesson({id:'private-offline-cache',unit:4,title:'Keep cached personal data bound to its owner',goal:'Audit exact origins, account switching, logout and application cache behavior.',basics:'The Cache API used by service workers is application-managed storage. It does not automatically obey HTTP caching headers or expire entries. A URL such as /users/me can return different data for two signed-in accounts, so a URL-only key can return the previous account\'s profile after a switch. Neither a small maxEntries setting nor a short TTL proves account isolation.',worked:'Choose whether personal responses should be cached at all. If they are, define account-bound keys, validation, expiry, invalidation on logout/account changes and safe offline behavior. Avoid retaining credentials in browser storage. Parse URLs and check the exact HTTPS origin. A pattern with optional http, such as (http)?://, allows insecure or missing schemes and does not match https as a scheme. Unanchored host substrings can also match attacker-controlled names.',code:'const url = new URL(request.url);\nconst allowed =\n  url.origin === "https://api.study.example";\n// Separately apply an explicit per-account cache policy.\n// Exact origin validation alone does not isolate accounts.',result:'HTTPS origin checking and cache ownership solve different problems. Both need their own policy.',pitfall:'Network-first and a shorter TTL are freshness strategies. They do not by themselves prevent cross-account disclosure.',question:'A and B share a browser and /users/me cache key. Which control addresses ownership?',choices:['Raise maxEntries from 1 to 10.','Use HTTP rather than HTTPS.','Bind entries to the account and invalidate them on account changes and logout.'],correct:2,feedback:'Ownership must follow the authenticated account, including offline and logout paths.',tasks:[['python','tcs-origin-check']],terms:[['Origin','Scheme, host and port considered together.'],['Invalidation','Removing or refusing a stored value when it should no longer be reused.']],sources:['offline','uri'],followUp:'Write a four-step account-switch test, including an offline request after logout.'}),
lesson({id:'xss-safe-output',unit:4,title:'Render untrusted text without executing it',goal:'Choose an output defense for the destination context.',basics:'Cross-site scripting occurs when untrusted content becomes executable browser content. Treat ordinary user text as text, for example through textContent. If building HTML templates, use the framework\'s context-appropriate escaping. HTML, attributes, URLs and JavaScript are different output contexts, so one generic string replacement does not secure all of them.',worked:'If a product intentionally accepts rich HTML, use a maintained sanitizer with a restrictive policy, then preserve the assumptions of that sanitized output. Validation can reject invalid inputs and CSP adds defense in depth, but neither replaces safe sinks and encoding. HTTPS protects transport, CAPTCHAs address some automated abuse, and passwords protect account access; none alone makes unsafe HTML rendering safe.',code:'const label = document.createElement("p");\nlabel.textContent = userSuppliedText;\n// The text is displayed rather than interpreted as HTML.',result:'Markup-shaped input remains visible text in this specific sink.',pitfall:'Do not promise that sanitizing all input solves every output context. Avoid creating executable strings from untrusted data.',question:'A comment is intended to be plain text. Which browser sink fits?',choices:['textContent.','innerHTML with raw comment text.','eval with the comment string.'],correct:0,feedback:'A safe text sink avoids interpreting markup. Rich HTML is a separate requirement with a separate sanitization policy.',terms:[['Sink','The destination where data is rendered or interpreted.'],['Output encoding','Representing data safely for a particular destination syntax.']],sources:['xss'],followUp:'Explain why a safe HTML-text strategy is not automatically safe for a URL or inline script.'}),
lesson({id:'sql-parameter-binding',unit:4,title:'Keep SQL structure separate from data values',goal:'Use bound values and fixed mappings for dynamic query structure.',basics:'SQL injection occurs when untrusted input changes query syntax. A parameterized query sends fixed SQL structure and separately bound values. An apostrophe in a search term then stays part of the value. Client-side validation is bypassable and regex filtering is not a structural replacement for binding. Server validation still enforces the application\'s valid data contract.',worked:'Parameters represent values, not table names, column names or keywords such as ASC. If a user chooses a sort option, map a small public option to an application-owned SQL fragment. Never concatenate that choice directly. Bound data can become unsafe later if another layer concatenates it into new dynamic SQL. Database permissions and safe stored-procedure construction remain relevant.',code:'# Python DB-API / SQLite illustration\ncursor.execute(\n    "SELECT id FROM notes WHERE owner_id = ? AND title = ?",\n    (owner_id, title)\n)',result:'title is bound as data, including quotes. The owner filter is still required independently of injection prevention.',pitfall:'Binding a value prevents it from becoming SQL syntax in this statement; it does not prove authorization or validate an entire application.',question:'How should a public sort choice select a database column?',choices:['Bind the column identifier as a value placeholder.','Map an allowed choice to a fixed application-owned column expression.','Concatenate any submitted column text.'],correct:1,feedback:'Placeholders are for data. Query structure should come from fixed code or an explicit allowlist mapping.',terms:[['Parameter','A separately bound data value.'],['Allowlist','An explicit set of accepted application-owned choices.']],sources:['injection'],followUp:'Explain what happens when a title contains an apostrophe, and why a separate owner check remains necessary.'}),
lesson({id:'oauth-callback-binding',unit:4,title:'Bind an OAuth callback to the login that started it',goal:'Understand authorization code, PKCE, state and exact redirect checking.',basics:'OAuth redirects a browser through an authorization server and back to a client. The callback must belong to the interaction this client started. Authorization code with PKCE binds a code to a verifier held by the initiating client. A session-bound, unpredictable, one-time state value is a common request/response correlation defense. Current guidance allows correctly supported PKCE to provide CSRF protection under its specified conditions; missing state alone is not enough to diagnose every flow.',worked:'Register and compare redirect destinations exactly under the applicable protocol rules. Validate state where used and reject missing, mismatched or replayed values. Avoid exposing tokens in browser-visible URLs. URL fragments are normally excluded from Referer, but scripts, browser state and redirect behavior can still expose fragment-carried tokens. Token exposure and login CSRF are different risks. This is an authored protocol walkthrough, not a live identity-provider integration.',code:'Start: create verifier + challenge and bind interaction\nAuthorize: request code, challenge, registered redirect, state\nCallback: validate interaction/state as applicable\nExchange: send code + verifier to the token endpoint\nReject: wrong redirect, failed binding or reused response',result:'A callback cannot be accepted merely because its URL contains a code.',pitfall:'Do not infer a complete exploit from one missing parameter without inspecting the actual PKCE/nonce/state protections.',question:'Which review is needed when an authorization request has no state?',choices:['Assume every such request is safe.','Claim its URL fragment is automatically sent in Referer.','Inspect the complete interaction binding, including supported PKCE and any applicable nonce protection.'],correct:2,feedback:'Assess the actual flow against current OAuth guidance. Individual parameter presence is not the entire security argument.',terms:[['PKCE','A code challenge/verifier mechanism binding code exchange to its initiator.'],['CSRF','An unwanted action induced through a user\'s authenticated browser context.']],sources:['oauth','http'],followUp:'Describe wrong-state, wrong-verifier and replay cases separately, without sending real tokens.'}),
lesson({id:'firebase-authorization',unit:4,title:'Distinguish public project settings from access rules',goal:'Evaluate configuration, authentication and ownership independently.',basics:'Firebase client project settings identify the project. The client API key is generally not a database password or an authorization grant. Actual database access depends on the product, requested path, operation and configured Security Rules. Authentication says who the caller is; authorization says whether that caller may perform this action on this data.',worked:'If email/password authentication is enabled, hiding a signup button does not prevent direct use of its supported API. Do not assume the provider is enabled by default. A rule that allows any authenticated user can be much broader than per-owner access. Assess reads, creates, updates and deletes separately. Prefer explicit user-identity/path checks and test unauthenticated, same-owner and different-owner cases using supported rule-test tools. This lesson contains no project credentials and performs no remote database operations.',code:'Illustrative policy matrix:\nUnauthenticated -> deny personal records\nOwner -> allow explicitly permitted operations\nDifferent user -> deny owner-only records\nPublic catalogue -> separate intentional read policy',result:'A public project identifier does not establish any row of this authorization matrix.',pitfall:'Neither an exposed client API key nor a hidden registration UI alone proves the effective database permissions.',question:'What establishes whether a signed-in stranger can delete another user\'s record?',choices:['The actual rules for that path and delete operation, including ownership.','Whether a signup button is visible.','Whether the public client configuration has been renamed.'],correct:0,feedback:'Evaluate the operation-specific authorization rules and enabled authentication setup, rather than treating configuration as a password.',terms:[['Authentication','Establishing the caller\'s identity.'],['Authorization','Deciding whether an identified or anonymous caller may act.']],sources:['firebase','firebaseKeys','firebaseAuth'],followUp:'Write owner and non-owner test cases for reading, updating and deleting the same record.'}),
lesson({id:'stratified-splits',unit:5,title:'Preserve class representation without claiming balance',goal:'Separate split strategy, class imbalance and evaluation metrics.',basics:'A dataset contains examples and target labels. A training set fits a model, validation data guides choices and a final test set estimates performance after those choices are fixed. Stratification preserves class proportions in the splits. It can keep a rare class represented when sample counts permit, but it does not make classes equally common or remove a majority-class bias.',worked:'For 80 majority and 20 minority examples, a proportional 25% test set has 20 and 5, not 12.5 each. The 4-to-1 ratio remains. Look at per-class precision/recall, confusion counts and metrics appropriate to the cost of mistakes. Grouped people or time-ordered data may require group/time splits to avoid leakage rather than random stratification. Very rare classes can make a requested split impossible; check counts first.',code:'Class             Total   Train   Test\nMajority             80      60     20\nMinority             20      15      5\nIllustration: a proportional 75/25 split',result:'Both splits preserve the original 4:1 class ratio. The imbalance remains.',pitfall:'Stratification is a sampling strategy, not a substitute for imbalance treatment or leakage-aware evaluation.',question:'What does this stratified split change?',choices:['It guarantees equal class counts.','It keeps approximate class proportions in each split.','It guarantees high minority recall.'],correct:1,feedback:'Representation is preserved. Performance and any reweighting/resampling choices still need separate evaluation.',terms:[['Stratification','Sampling within label groups to preserve proportions.'],['Leakage','Information available during evaluation that would not be available for a real new prediction.']],sources:['split'],followUp:'Make the same table for 90 and 10 examples. Explain why a patient-level dataset may need grouped splitting.'}),
lesson({id:'regularization-and-validation',unit:5,title:'Reduce overfitting without tuning on the final test',goal:'Read training and validation evidence before choosing regularization.',basics:'Overfitting means fitting training-specific patterns that do not generalize. A model with excellent training performance and much worse validation performance may be overfitting, though leakage, distribution shift or bad measurement also deserve investigation. Regularization limits effective flexibility, for example through weight penalties. Model-specific dropout and early stopping are other common controls.',worked:'Compare candidates using suitable validation data. More regularization is not always better: excessive constraints can underfit both training and validation data. Choose a setting through validation or cross-validation, then reserve the final test set for the settled process. Repeatedly tuning to the final test adapts the process to that test and weakens its value as an independent estimate. Authored numbers below illustrate the trade-off; they are not results from a trained model.',code:'Penalty      Training error   Validation error\nWeak                   1%                 18%\nModerate               8%                 11%\nExcessive             30%                 32%',result:'The moderate setting has the lowest illustrated validation error. Excessive regularization underfits.',pitfall:'Regularization can improve generalization; it does not guarantee it or repair an invalid evaluation split.',question:'How should the illustrated penalty be selected?',choices:['Always choose the strongest penalty.','Keep changing it until the final test looks best.','Compare validation performance and keep the final test separate.'],correct:2,feedback:'The selection process uses validation. An untouched final test evaluates the resulting choice.',terms:[['Underfitting','A model is too restricted to capture useful patterns.'],['Hyperparameter','A setting chosen outside the ordinary fitted parameter updates.']],sources:['regularization','split'],followUp:'Explain why random feature deletion is not the same as validated feature selection.'}),
lesson({id:'few-shot-versus-training',unit:5,title:'Adapt a prompt without changing model weights',goal:'Distinguish in-context examples from fine-tuning and QLoRA.',basics:'A prompt can include instructions and a few examples showing the desired task. This is often called few-shot or in-context learning. The model uses those examples during inference without gradient updates to its weights. The effect depends on the supplied context; it is not a promise of permanent model learning. Examples still consume context length and inference work.',worked:'Fine-tuning performs optimization updates. Parameter-efficient methods update a smaller set of parameters or adapters, and QLoRA combines low-bit base-model handling with adapter training. These are useful techniques but do not satisfy a strict no-weight-update constraint. Distinguish few-shot prompting from instruction tuning on example data, which is still training. The demonstration below is an authored prompt, with no model service invoked.',code:'Task: label a support message as billing or access.\nExamples:\n"My receipt is missing" -> billing\n"I cannot sign in" -> access\nNew message: "Please resend my invoice"\nReturn one label.',result:'The examples steer inference. No training run or model-weight change is performed by this lesson.',pitfall:'The word learning in in-context learning does not imply a gradient update or persistent memory.',question:'Which technique fits a strict no-gradient-update constraint?',choices:['Few-shot examples inside the inference prompt.','QLoRA adapter training.','Instruction fine-tuning on the examples.'],correct:0,feedback:'Prompt examples alter the context supplied to inference. The other choices involve training updates.',terms:[['Inference','Using a model to produce an output.'],['Fine-tuning','Training updates that adapt model parameters or adapters.']],sources:['fewshot'],followUp:'Change one example label deliberately and explain what you would evaluate before trusting the new prompt.'}),
lesson({id:'rag-evaluation',unit:5,title:'Evaluate retrieval, support, correctness and safety separately',goal:'Avoid treating fluent text or one score as proof of a trustworthy answer.',basics:'Retrieval-augmented generation supplies retrieved information to a generator. Retrieval quality asks whether useful documents were found. Grounding asks whether answer claims are supported by that supplied context. Real-world correctness asks whether the evidence and claims are true and current. Domain safety asks whether the output is appropriate for its use. These dimensions can disagree.',worked:'An answer can faithfully repeat an outdated source and still be wrong. A retrieved document can be relevant while the generated answer invents a conclusion. Text-overlap metrics such as ROUGE do not establish factual correctness. A knowledge graph can provide structured checks, but an incomplete or erroneous graph is not a truth oracle. High-stakes domain evaluation needs reviewed references and qualified human oversight. The worked case is about a fictional device manual, not clinical advice or a live RAG system.',code:'Source: "Model K supports wired charging only."\nAnswer A: "Model K supports wired charging."\nAnswer B: "Model K supports wireless charging."\nReview axes: retrieval, claim support, source validity, use risk',result:'A is supported by this source. B contradicts it. Neither comparison establishes that the fictional source matches a real product.',pitfall:'A relevant source, a confident answer, or a knowledge-graph match is not sufficient evidence for every evaluation dimension.',question:'An answer accurately repeats an outdated document. Which distinction matters?',choices:['Grounding guarantees current correctness.','Grounding and real-world correctness must be evaluated separately.','High wording overlap proves domain safety.'],correct:1,feedback:'Support measures agreement with supplied evidence. Correctness also depends on the evidence\'s validity and freshness.',terms:[['Grounding','Relating answer claims to supplied evidence.'],['Retrieval recall','How much of the relevant information the retrieval step finds.']],sources:['rag'],followUp:'Design a rubric that records retrieval, supported claims, source validity and harm risk as separate findings.'}),
lesson({id:'grounding-and-abstention',unit:5,title:'Check claims and leave unsupported gaps unanswered',goal:'Explain both the usefulness and limits of hallucination controls.',basics:'A generated claim can be unsupported even when it sounds fluent. Grounding instructions can ask a model to use only supplied evidence, cite supporting passages and abstain when evidence is missing. Those instructions need evaluation. A lower temperature reduces sampling variability; it does not turn a false or biased distribution into a reliable fact source.',worked:'Self-verification and comparing multiple generated answers may help on some tasks, but repeated agreement can repeat the same error. Check each consequential claim against authoritative evidence, including contradictions and missing details. If a source says only that a shop opens at 9, its closing time remains unknown. Do not invent the missing time or treat a shorter answer as inherently more factual. This lesson uses an authored evidence comparison and makes no remote model call.',code:'Evidence: "The help desk opens at 09:00 on weekdays."\nClaim: "It closes at 17:00."\nSupported response: "The closing time is not stated."',result:'Abstention preserves the evidence boundary. The missing closing time is not supplied by confidence or repeated guesses.',pitfall:'Low temperature, majority agreement and self-checking are mitigation tools, not correctness guarantees.',question:'Five generated answers agree on a closing time absent from the source. What is established?',choices:['The majority has verified the time.','Lower temperature would make it a fact.','Only agreement is established; the closing-time claim is still unsupported.'],correct:2,feedback:'Agreement is different from independent source evidence. Ask for a source or state the gap.',terms:[['Abstention','Declining a claim when sufficient evidence is unavailable.'],['Self-consistency','Comparing multiple generated paths or answers, with task-dependent benefits.']],sources:['rag','consistency'],followUp:'List the exact source evidence needed to turn an unsupported claim into a supported one.'}),
lesson({id:'flow-termination',unit:6,title:'Find the value that controls a loop back edge',goal:'Trace state changes and explain termination using a progress measure.',basics:'A flowchart decision is a condition, a box is an operation and a back edge repeats earlier work. Translate those into a small program or state table. List the variables read by the condition and identify which assignments can change them. Changing an unrelated variable cannot make an invariant true condition become false.',worked:'The example subtracts two from counter, so a positive counter approaches the stopping condition. If the body changed only a note field, counter would remain six and this guard would stay true. Reversing a comparison can create or remove a cycle, but the result depends on the actual values and writes. Use a bounded trace or a stop control when experimenting; do not animate a fixed answer that ignores edited code.',code:'counter, visits = 6, []\nwhile counter > 0:\n    visits.append(counter)\n    counter -= 2\nprint(visits)\nprint(counter)',result:'[6, 4, 2]\n0',pitfall:'A loop body can do work forever without changing the condition that controls its repetition.',question:'The guard is counter > 0 and counter is 6. Which change would leave it permanently true?',choices:['Only incrementing a separate note_count variable, never changing counter.','Subtracting two from counter each iteration.','Setting counter to zero.'],correct:0,feedback:'Only variables affecting the guard can provide progress toward making that guard false.',tasks:[['python','tcs-loop-progress']],terms:[['Back edge','A control-flow connection to an earlier step.'],['Invariant','A fact that remains true through the relevant steps.']],sources:['python'],followUp:'Complete the mixed review, then write one SQL answer and one Python answer from blank with changed data.'})
];
export const TCS_BY_ID=new Map(TCS_LESSONS.map(x=>[x.id,x]));
export const TCS_REVIEW_IDS=['choose-a-deque','sql-left-join-count','git-three-snapshots','private-offline-cache','oauth-callback-binding','stratified-splits','grounding-and-abstention','flow-termination'];
